using System.Drawing;
namespace WindowsApplication1;
internal static class Resources
{
    internal static Bitmap clipboard { get; } = Read("");
    internal static Bitmap doc_icon { get; } = Read("");
    internal static Bitmap ims_ORB_logo { get; } = Read("");
    private static Bitmap Read(string data)
    {
        using var stream = new System.IO.MemoryStream(System.Convert.FromBase64String(data));
        using var image = System.Drawing.Image.FromStream(stream);
        return new Bitmap(image);
    }
}